def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
def lcm(a, b):
    return a * b // gcd(a, b)
print(gcd(48, 36), gcd(17, 5), lcm(4, 6), lcm(21, 6), gcd(0, 7))

def qsort(a):
    if len(a) <= 1:
        return a
    p = a[0]
    left = []
    right = []
    for x in a[1:]:
        if x < p:
            left.append(x)
        else:
            right.append(x)
    return qsort(left) + [p] + qsort(right)
print(qsort([8, 3, 9, 1, 5, 5, 2, 7]))

def flatten(x):
    out = []
    for item in x:
        if isinstance(item, list):
            for sub in flatten(item):
                out.append(sub)
        else:
            out.append(item)
    return out
print(flatten([1, [2, [3, [4, 5]], 6], 7]))
print(flatten([]), flatten([[[[]]]]))
print(flatten([1, [2], [[3], 4], 'ab']))

memo = {0: 0, 1: 1}
def fib(n):
    if n in memo:
        return memo[n]
    r = fib(n - 1) + fib(n - 2)
    memo[n] = r
    return r
print([fib(i) for i in range(12)], fib(25))

